// Fork of "Vasarely - 1" https://shadertoy.com/view/MldSR8

void mainImage( out vec4 O,  vec2 U )
{
	vec2  R = iResolution.xy;
          U = 10.5 * ( U+U - R ) / R.y;                                       // normalized coordinates
	float L = length(U), l, e = 15./R.y, a;

    O *= 0.;
    if (abs(U.x) > 10.5) return;                                              // figure only in square

    U /= L > 8.5 ? 1. : mix(1.,3.-L*L/36.,smoothstep(8.5, 7., L));            // scarletshark's domain warping
                     // 3.-L*L/36.;
    l = length( 2.*fract(U +.5) - 1. );                                       // disc pattern in tiles

    U = ceil(U-.5); R = abs(U)+1.;                                            // cell id (with symmetries)
    a = U.x*U.y;

    O = mix( R.x+R.y<13.  ? vec4(1,.2,.15,1) : vec4(.25,.5,.25,1),            // inner
        mix( L<8.5||a<1.  ? vec4(.15,.2,.5,1): vec4(1,.2,.15,1),              // mid
             mix( vec4(.55,.75,.35,1), a/1e2*vec4(-1,0,1,1), .1*length(R) ),  // outer
             smoothstep(-e,e,l-1.) ),
           smoothstep(-e,e,l-.7) );

}
